	/** 
	 * jumpstart the process by instantiating2 Issue
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		issueId = IssueService.getIssueInstance()
		.createIssue( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		IssueService.getIssueInstance()
				.createIssue( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.issueSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Issue : " + successValue.getIssueId());
							  if (successValue.getIssueId().equals(issueId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfIssueList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Issue test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on issue consumed")
					);
			subscriber.issueSubscribe( issueId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Issue : " + successValue.getIssueId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfIssueList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on issue for issueId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Issue. 
	 */
	protected Issue read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Issue" );

		Issue entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Issue with primary key" );
		msg.append( issueId );
		
		IssueFetchOneSummary fetchOneSummary = new IssueFetchOneSummary( issueId );

		try {
			entity = IssueService.getIssueInstance().getIssue( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Issue " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Issue.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Issue." );

		StringBuilder msg = new StringBuilder( "Failed to update a Issue : " );        
		Issue entity = read();
		UpdateIssueCommand command = generateUpdateCommand();
		command.setIssueId(entity.getIssueId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Issue." );

			// for use later on...
			issueId = entity.getIssueId();

			IssueService proxy = IssueService.getIssueInstance();  

			proxy.updateIssue( command ).get();

			LOGGER.info( "-- Successfully saved Issue - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + issueId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Issue.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Issue." );

		Issue entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Issue with id " + issueId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Issue with id " + issueId );

			throw e;
		}

		try{
			IssueService.getIssueInstance().delete( new DeleteIssueCommand( entity.getIssueId() ) ).get();
			LOGGER.info( "-- Successfully deleted Issue with id " + issueId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Issue with id " + issueId );

			throw e;
		}
	}

	/**
	 * get all Issues.
	 */
	protected List<Issue> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Issues:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Issue : " );        
		List<Issue> collection  = new ArrayList<>();

		try {
			// call the static get method on the IssueService
			collection = IssueService.getIssueInstance().getAllIssue();
			assertNotNull( collection, "An Empty collection of Issue was incorrectly returned.");
			
			// Now print out the values
			Issue entity = null;            
			Iterator<Issue> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getIssueId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

